function lower_bound(a, target):
    left = 0
    right = length(a)               # полуинтервал [left, right)
    while left < right:
        mid = left + floor((right - left) / 2)
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

function has_overlap(intervals):
    # Интервалы [start, end); start < end
    sorted_intervals = sort(intervals, key = start)
    max_end = -INFINITY
    for interval in sorted_intervals:
        if interval.start >= interval.end:
            return INVALID_INPUT
        if interval.start < max_end:
            return TRUE
        max_end = max(max_end, interval.end)
    return FALSE

function bfs_distances(graph, source):
    # graph[v] — список соседей вершины v
    distance = array(length(graph), fill = -1)
    queue = FIFOQueue()
    distance[source] = 0
    queue.push(source)
    while NOT queue.empty():
        v = queue.pop()
        for neighbor in graph[v]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[v] + 1
                queue.push(neighbor)
    return distance

function min_coins(coins, amount):
    # Все номиналы строго положительны
    dp = array(amount + 1, fill = INFINITY)
    dp[0] = 0
    for value from 1 to amount:
        for coin in coins:
            if coin <= value AND dp[value - coin] != INFINITY:
                dp[value] = min(dp[value], dp[value - coin] + 1)
    if dp[amount] == INFINITY: return NOT_FOUND
    return dp[amount]

